<template><div><el-select v-model="selected" placeholder="选择智能体"><el-option v-for="a in agents" :key="a.id" :label="a.name" :value="a.id"/></el-select><el-button @click="bind(false)">绑定</el-button><el-table :data="bindings"><el-table-column prop="name" label="已绑定智能体"/><el-table-column prop="realtimeMode" label="实时模式"/><el-table-column prop="status" label="状态"/><el-table-column label="默认智能体"><template #default="{row}"><el-switch :model-value="row.defaultAgent" @change="setDefault(row)"/></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="unbind(row)">解绑</el-button></template></el-table-column></el-table></div></template><script setup lang="ts">import{onMounted,ref}from'vue';import{AiAgentApi,type AgentVO}from'@/api/ai/agent';const p=defineProps<{robotId:number}>();const agents=ref<AgentVO[]>([]),bindings=ref<any[]>([]),selected=ref<number>();async function load(){agents.value=await AiAgentApi.list();const all=await Promise.all(agents.value.map(async a=>({a,bs:await AiAgentApi.listRobots(a.id)})));bindings.value=all.flatMap(x=>x.bs.filter(b=>b.robotId===p.robotId).map(b=>({...b,name:x.a.name,realtimeMode:x.a.realtimeMode})))}async function bind(def:boolean){if(selected.value){await AiAgentApi.bindRobot(selected.value,p.robotId,def);await load()}}async function setDefault(row:any){await AiAgentApi.bindRobot(row.agentId,p.robotId,true);await load()}async function unbind(row:any){await AiAgentApi.unbindRobot(row.agentId,p.robotId);await load()}onMounted(load)</script>